def generate_parentheses(n: int) -> list[str]:
    def backtrack(partial: str, open_count: int, close_count: int, n: int, result: list[str]) -> None:
        if len(partial) == 2 * n:
            result.append(partial)
            return
        if open_count < n:
            backtrack(partial + '(', open_count + 1, close_count, n, result)
        if close_count < open_count:
            backtrack(partial + ')', open_count, close_count + 1, n, result)
    result: list[str] = []
    backtrack('', 0, 0, n, result)
    return result

def stooge_sort(array: list[int]) -> list[int]:
    def _stooge_sort(array: list[int], low: int, high: int) -> None:
        if low >= high:
            return
        if array[low] > array[high]:
            array[low], array[high] = (array[high], array[low])
        if high - low + 1 > 2:
            third = (high - low + 1) // 3
            _stooge_sort(array, low, high - third)
            _stooge_sort(array, low + third, high)
            _stooge_sort(array, low, high - third)
    _stooge_sort(array, 0, len(array) - 1)
    return array

def variance(iterable, sample=False):
    def mean(iterable):
        a = iterable if isinstance(iterable, list) else list(iterable)
        return float(sum(a)) / (len(a) or 1)
    a = iterable if isinstance(iterable, list) else list(iterable)
    m = mean(a)
    return sum(((x - m) ** 2 for x in a)) / (len(a) - int(sample) or 1)

def is_strong_number(number: int) -> bool:
    def factorial(digit: int) -> int:
        return 1 if digit in (0, 1) else digit * factorial(digit - 1)
    fact_sum = 0
    duplicate = number
    while duplicate > 0:
        duplicate, digit = divmod(duplicate, 10)
        fact_sum += factorial(digit)
    return fact_sum == number

def catalan_number(node_count: int) -> int:
    def binomial_coefficient(n: int, k: int) -> int:
        result = 1
        k = min(k, n - k)
        for i in range(k):
            result *= n - i
            result //= i + 1
        return result
    return binomial_coefficient(2 * node_count, node_count) // (node_count + 1)

def next_prime(number: int) -> int:
    def is_prime(number: int) -> bool:
        if number <= 1:
            return False
        if number <= 3:
            return True
        if number % 2 == 0 or number % 3 == 0:
            return False
        factor = 5
        while factor * factor <= number:
            if number % factor == 0 or number % (factor + 2) == 0:
                return False
            factor += 6
        return True
    if not isinstance(number, int):
        raise ValueError('next_prime() only accepts integral values')
    candidate = number + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate
